        vr, vc = vertical
        hr, hc = horizontal
        for up in (True, False):
            for left in (True, False):
                pts = {(r, c) for r, c in sevens
                       if r != hr and c != vc
                       and (r < hr) == up and (c < vc) == left}
                for comp in components(pts):
                    move(comp, up, left)

        for r, c in sevens:
            if r == hr or c == vc:
                out[r][c] = 7

        aligned = [r for r, c in sevens if c == vc]
        if aligned:
            end = max(aligned) if vr == 0 else min(aligned)
            rows = range(end + 1) if vr == 0 else range(end, h)
        else:
            # With two edge markers, the empty axis runs to their intersection.
            rows = range(hr + 1) if vr == 0 else range(hr, h)
        for r in rows:
            if grid[r][vc] != 7:
                out[r][vc] = 2

        aligned = [c for r, c in sevens if r == hr]
        if aligned:
            end = max(aligned) if hc == 0 else min(aligned)
            cols = range(end + 1) if hc == 0 else range(end, w)
        else:
            cols = range(vc + 1) if hc == 0 else range(vc, w)
        for c in cols:
            if grid[hr][c] != 7:
                out[hr][c] = 2

    elif vertical:
        vr, vc = vertical
        for left in (True, False):
            pts = {(r, c) for r, c in sevens
                   if c != vc and ((c < vc) == left)}
            for comp in components(pts):
                move(comp, vr == 0, left)

        aligned = [r for r, c in sevens if c == vc]
        if aligned:
            end = max(aligned) if vr == 0 else min(aligned)
            rows = range(end + 1) if vr == 0 else range(end, h)
            for r in rows:
                if grid[r][vc] != 7:
                    out[r][vc] = 2
        for r, c in sevens:
            if c == vc:
                out[r][c] = 7

    elif horizontal:
        hr, hc = horizontal
        for up in (True, False):
            pts = {(r, c) for r, c in sevens
                   if r != hr and ((r < hr) == up)}
            for comp in components(pts):
                move(comp, up, hc == 0)

        aligned = [c for r, c in sevens if r == hr]
        if aligned:
            end = max(aligned) if hc == 0 else min(aligned)
            cols = range(end + 1) if hc == 0 else range(end, w)
            for c in cols:
                if grid[hr][c] != 7:
                    out[hr][c] = 2
        for r, c in sevens:
            if r == hr:
                out[r][c] = 7

    for r, c in markers:
        out[r][c] = 2
    return out
